#[cfg(memory_measurement)]
mod heap {
    use std::alloc::{GlobalAlloc, Layout, System};
    use std::sync::atomic::{AtomicUsize, Ordering::Relaxed};
    pub static LIVE: AtomicUsize = AtomicUsize::new(0);
    pub static PEAK: AtomicUsize = AtomicUsize::new(0);
    pub struct Counted;
    fn add(bytes: usize) {
        let live = LIVE.fetch_add(bytes, Relaxed) + bytes;
        PEAK.fetch_max(live, Relaxed);
    }
    unsafe impl GlobalAlloc for Counted {
        unsafe fn alloc(&self, layout: Layout) -> *mut u8 {
            let pointer = unsafe { System.alloc(layout) };
            if !pointer.is_null() {
                add(layout.size());
            }
            pointer
        }
        unsafe fn dealloc(&self, pointer: *mut u8, layout: Layout) {
            LIVE.fetch_sub(layout.size(), Relaxed);
            unsafe { System.dealloc(pointer, layout) };
        }
        unsafe fn realloc(&self, pointer: *mut u8, layout: Layout, new_size: usize) -> *mut u8 {
            let result = unsafe { System.realloc(pointer, layout, new_size) };
            if !result.is_null() {
                if new_size >= layout.size() {
                    add(new_size - layout.size());
                } else {
                    LIVE.fetch_sub(layout.size() - new_size, Relaxed);
                }
            }
            result
        }
    }
}
#[cfg(memory_measurement)]
#[global_allocator]
static ALLOCATOR: heap::Counted = heap::Counted;

type Merge = fn(Vec<FileChange>, Vec<FileChange>) -> Vec<FileChange>;

fn fixture(n: usize, path_bytes: usize, overlap: bool) -> (Vec<FileChange>, Vec<FileChange>) {
    let make = |index: usize, committed: bool| {
        let path = GitPath(format!("{:0width$}", index, width = path_bytes).into_bytes());
        FileChange {
            path: path.clone(),
            old_path: (index % 3 == 0).then(|| GitPath(b"old-name".to_vec())),
            staged: !committed && index % 2 == 0,
            unstaged: !committed,
            untracked: !committed && index % 5 == 0,
            conflict: !committed && index % 7 == 0,
            status: if committed { "M" } else { " M" }.into(),
            committed: committed.then(|| CommittedComparison {
                base: "1".repeat(40),
                head: "2".repeat(40),
                path,
                old_path: (index % 3 == 0).then(|| GitPath(b"committed-old".to_vec())),
                status: "M".into(),
            }),
        }
    };
    if overlap {
        ((0..n).map(|i| make(i, false)).collect(), (0..n).map(|i| make(i, true)).collect())
    } else {
        ((0..n / 2).map(|i| make(i, false)).collect(), (n / 2..n).map(|i| make(i, true)).collect())
    }
}

fn main() {
    let args: Vec<String> = std::env::args().collect();
    let n: usize = args[1].parse().unwrap();
    let path_bytes: usize = args[2].parse().unwrap();
    let overlap = args[3] == "overlap";
    let indexed = args[4] == "indexed";
    let merge: Merge = if indexed { merge_changes } else { old_merge };
    let (working, committed) = fixture(n, path_bytes, overlap);
    #[cfg(not(memory_measurement))]
    {
        let expected = old_merge(working.clone(), committed.clone());
        assert_eq!(expected, merge_changes(working.clone(), committed.clone()));
        assert_eq!(expected.len(), n);
        for (i, record) in expected.iter().enumerate() {
            assert_eq!(record.path.0, format!("{:0width$}", i, width = path_bytes).into_bytes());
        }
        for sample in 0..6 {
            let left = working.clone();
            let right = committed.clone();
            let start = Instant::now();
            let result = black_box(merge(black_box(left), black_box(right)));
            let elapsed = start.elapsed().as_nanos();
            assert_eq!(result, expected);
            if sample > 0 {
                println!("{{\"sample\":{},\"ns\":{}}}", sample, elapsed);
            }
        }
    }
    #[cfg(memory_measurement)]
    {
        use std::sync::atomic::Ordering::Relaxed;
        let baseline = heap::LIVE.load(Relaxed);
        heap::PEAK.store(baseline, Relaxed);
        let result = black_box(merge(black_box(working), black_box(committed)));
        let peak = heap::PEAK.load(Relaxed);
        let retained = heap::LIVE.load(Relaxed);
        assert_eq!(result.len(), n);
        println!("{{\"input_live_bytes\":{},\"peak_live_bytes\":{},\"peak_above_input_bytes\":{},\"after_merge_live_bytes\":{},\"file_change_bytes\":{}}}", baseline, peak, peak - baseline, retained, std::mem::size_of::<FileChange>());
    }
}

